class Solution {
    public:vector<vector<int>> spiralMatrix(int m,int n,ListNode* head){
        vector matrix(m,vector<int>(n,-1));
        int directions[5]={
            0,1,0,-1,0
        },row=0,column=0,direction=0;
        for(ListNode* node=head;node;node=node->next){
            matrix[row][column]=node->val;
            int nr=row+directions[direction],nc=column+directions[direction+1];
            if(nr<0||nr>=m||nc<0||nc>=n||matrix[nr][nc]!=-1){
                direction=(direction+1)%4;
                nr=row+directions[direction];
                nc=column+directions[direction+1];
            }
            row=nr;
            column=nc;
        }
        return matrix;
    }
